import sys

def solve():
    s = sys.stdin.read().strip()
    n = len(s)

    # dp[i] will store the length of the longest regular bracket sequence ending at index i
    dp = [0] * n

    max_len = 0
    count = 0

    for i in range(n):
        if s[i] == ')':
            if i > 0 and s[i-1] == '(':
                # Case: ...()
                prev_len = dp[i-1]
                current_len = 2
                if i - 2 >= 0:
                    current_len += dp[i-2]
                dp[i] = current_len
            elif i > 1 and s[i-1] == ')':
                # Case: ...)) where inner part is valid
                prev_len = dp[i-1]
                if prev_len > 0:
                    # Check the character before the previous valid sequence
                    j = i - prev_len - 1
                    if j >= 0 and s[j] == '(':
                        current_len = prev_len + 2
                        # Add any valid sequence before the matching '('
                        if j - 1 >= 0:
                            current_len += dp[j-1]
                        dp[i] = current_len

            if dp[i] > 0:
                if dp[i] > max_len:
                    max_len = dp[i]
                    count = 1
                elif dp[i] == max_len:
                    count += 1

    if max_len == 0:
        print("0 1")
    else:
        print(f"{max_len} {count}")

if __name__ == "__main__":
    solve()
